  ($q$pd-526$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$One-variable data$q$, 1, null, $q$The mean of five numbers is 20. Four of the numbers are 17, 22, 18, 14. What is the fifth number?$q$, $q$["49","29","28","20"]$q$::jsonb, 1, $q$The five numbers sum to 20 × 5 = 100. The four known numbers sum to 71, so the fifth is 100 − 71 = 29.$q$, null),
  ($q$pd-527$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Percentages$q$, 1, null, $q$A store's weekly sales, in thousands of dollars changed from 80 to 40. By what percent did it decrease?$q$, $q$["60%","40%","50%","100%"]$q$::jsonb, 2, $q$Percent change = (change)/(original) × 100 = 40/80 × 100 = 50%.$q$, null),
  ($q$pd-528$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Percentages$q$, 1, null, $q$A group of 300 members of a hiking club was surveyed, and 25% of them own a tent. How many of the people surveyed responded that they own a tent?$q$, $q$["225","75","100","55"]$q$::jsonb, 1, $q$25% of 300 is 0.25 × 300 = 75.$q$, null),
