  ($q$pd-643$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$One-variable data$q$, 1, null, $q$What is the median of the data set 12, 29, 39, 9, 9, 27, 2?$q$, $q$["39","9","12","18"]$q$::jsonb, 2, $q$In order: 2, 9, 9, 12, 27, 29, 39. The middle (4th) value is 12.$q$, null),
